<?php
declare(strict_types=1);
$privateRoot=__DIR__.'/smayo_private';
require $privateRoot.'/app/bootstrap.php';
$locale=requested_locale();
$direction=$locale==='ar'?'rtl':'ltr';
$menuOpenLabel=$locale==='ar'?'فتح القائمة':'Open navigation';
$languageLabel=$locale==='ar'?'اللغة':'Language';
$requestPath=(string)(parse_url((string)($_SERVER['REQUEST_URI']??'/'),PHP_URL_PATH)??'/');
$basePath=site_base_path();
$rootPath=rtrim($basePath,'/').'/';
if($requestPath===$rootPath||$requestPath===$basePath||$requestPath===$rootPath.'index.php'||$requestPath==='/index.php'){header('Location: '.localized_page_url($locale),true,302);exit;}
if(preg_match('#^'.preg_quote(rtrim($basePath,'/'),'#').'/[a-z]{2,3}(?:-[a-z]{2})?/?$#i',$requestPath)&&!preg_match('#/(?:en|ar)/?$#i',$requestPath)){header('Location: '.localized_page_url('en'),true,302);exit;}
$preview=isset($_GET['preview'])&&$_GET['preview']==='1';
if($preview&&!current_user()){http_response_code(403);exit('Administrator login required.');}
try{$data=content_doc('site',$preview);$design=content_doc('design',$preview);$sections=content_doc('sections',$preview);$settings=$data['settings']??[];$design=$design['design']??[];$sections=$sections['sections']??[];}
catch(Throwable $e){http_response_code(503);error_log('SMayo public content: '.$e->getMessage());exit('The website is temporarily unavailable.');}
function image_tag(?int $id,string $alt='',string $class='content-image'): string { $asset=media_by_id($id);if(!$asset)return '';return '<img class="'.e($class).'" src="'.e(site_public_url('uploads/'.rawurlencode($asset['filename']))).'" alt="'.e($alt!==''?$alt:$asset['alt_text']).'" loading="lazy">'; }
function render_section(array $section,array $siteSettings=[],string $locale='en'): string {
  $type=(string)($section['type']??'');$arrow=$locale==='ar'?'←':'→';$c=$section['content']??[];if(!is_array($c))return '';$c=localized_content($c,$locale,$section['translations'][$locale]??null);$id=preg_replace('/[^A-Za-z0-9_-]/','-',(string)($section['id']??$type));
  $head='<div class="section-heading">'.(!empty($c['eyebrow'])?'<span class="eyebrow">'.e($c['eyebrow']).'</span>':'').(!empty($c['title'])?'<h2>'.e($c['title']).'</h2>':'').(!empty($c['description'])?'<p>'.e($c['description']).'</p>':'').'</div>';
  $out='';
  if($type==='hero'){$out='<section class="hero" id="'.e($id).'"><div class="hero-copy"><span class="eyebrow">'.e($c['eyebrow']??'').'</span><h1>'.e($c['title']??'').'</h1><p>'.e($c['description']??'').'</p>'.(!empty($c['button_label'])?'<a class="button" href="'.e(safe_link($c['button_href']??'#contact',$locale)).'">'.e($c['button_label']).' '.e($arrow).'</a>':'').'</div>'.image_tag(isset($c['image_id'])?(int)$c['image_id']:null,(string)($c['image_alt']??''),'hero-image').'</section>';}
  elseif($type==='about'){$out='<section class="section about" id="'.e($id).'">'.$head.'<div class="two-column">'.image_tag(isset($c['image_id'])?(int)$c['image_id']:null,(string)($c['image_alt']??'')).'<p>'.nl2br(e($c['body']??'')).'</p></div></section>';}
  elseif(in_array($type,['services','features','statistics','testimonials','gallery'],true)){$items=is_array($c['items']??null)?$c['items']:[];$out='<section class="section" id="'.e($id).'">'.$head.'<div class="grid '.e($type).'">';foreach($items as $item){if(!is_array($item))continue;$out.='<article class="tile">';if($type==='services'||$type==='gallery')$out.=image_tag(isset($item['image_id'])?(int)$item['image_id']:null,(string)($item['image_alt']??''));if($type==='statistics')$out.='<strong class="stat">'.e($item['value']??'').'</strong>';elseif($type==='testimonials')$out.='<blockquote>“'.e($item['quote']??'').'”</blockquote>';if(!empty($item['title']))$out.='<h3>'.e($item['title']).'</h3>';if(!empty($item['description']))$out.='<p>'.e($item['description']).'</p>';if(!empty($item['label']))$out.='<p>'.e($item['label']).'</p>';if(!empty($item['name']))$out.='<small>'.e($item['name']).(!empty($item['role'])?' · '.e($item['role']):'').'</small>';$out.='</article>';}$out.='</div></section>';}
  elseif($type==='cta'){$out='<section class="cta" id="'.e($id).'"><span class="eyebrow">'.e($c['eyebrow']??'').'</span><h2>'.e($c['title']??'').'</h2><p>'.e($c['description']??'').'</p><a class="button" href="'.e(safe_link($c['button_href']??'#contact',$locale)).'">'.e($c['button_label']??'Contact us').' '.e($arrow).'</a></section>';}
  elseif($type==='contact'){$contactEmail=trim((string)($c['email']??''))?:trim((string)($siteSettings['email']??''));$buttonHref=trim((string)($c['button_href']??''));if($buttonHref===''&&$contactEmail!=='')$buttonHref='mailto:'.$contactEmail;$out='<section class="section contact" id="'.e($id).'">'.$head.'<div class="contact-info">'.(!empty($c['email'])?'<a href="mailto:'.e($c['email']).'">'.e($c['email']).'</a>':'').(!empty($c['phone'])?'<a href="tel:'.e($c['phone']).'">'.e($c['phone']).'</a>':'').(!empty($c['location'])?'<span>'.e($c['location']).'</span>':'').'</div>'.(!empty($c['button_label'])?'<a class="button" href="'.e(safe_link($buttonHref!==''?$buttonHref:'#contact',$locale)).'">'.e($c['button_label']).' '.e($arrow).'</a>':'').'</section>';}
  return $out;
}
$safeColor=static fn($v,$default)=>is_string($v)&&preg_match('/^(#[0-9a-fA-F]{3,8}|rgba?\([\d.,%\s\/+-]+\))$/',$v)?$v:$default;
$settings=localized_content($settings,$locale);
$safeSize=static fn($v,$default)=>is_string($v)&&preg_match('/^\d+(\.\d+)?(px|rem|em|%)$/',$v)?$v:$default;
$safeFont=static fn($v,$default)=>is_string($v)&&preg_match('/^[-\w ,]{1,120}$/',$v)?$v:$default;
$canonicalEn=canonical_locale_url('en');
$canonicalAr=canonical_locale_url('ar');
$canonicalCurrent=$locale==='ar'?$canonicalAr:$canonicalEn;
function safe_link(mixed $value,string $locale='en'): string {
  $url=trim((string)$value);
  if(!preg_match('/^(#|\/(?!\/)|\.\/|\.\.\/)/',$url)&&!preg_match('/^(https?:|mailto:|tel:)/i',$url))return '#';
  if($url===''||$url[0]==='#'||preg_match('/^(https?:|mailto:|tel:)/i',$url)||$url[0]!== '/')return $url===''?'#':$url;
  $parts=parse_url($url);if(!is_array($parts))return '#';$path=(string)($parts['path']??'/');$base=rtrim(site_base_path(),'/');$root=$base===''?'/':$base.'/';$target=null;
  if($path==='/'||$path===$base||$path===$root)$target=site_public_url($locale.'/');
  elseif(preg_match('#^'.preg_quote($root,'#').'(?:en|ar)(/.*)?$#i',$path,$match))$target=site_public_url($locale.'/'.ltrim((string)($match[1]??''),'/'));
  if($target===null)return $url;
  return $target.(isset($parts['query'])?'?'.$parts['query']:'').(isset($parts['fragment'])?'#'.$parts['fragment']:'');
}
?><!doctype html><html lang="<?=e($locale)?>" dir="<?=e($direction)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=e($settings['tagline']??'')?>"><title><?=e($settings['brand']??'SMayo')?></title><link rel="canonical" href="<?=e($canonicalCurrent)?>"><link rel="alternate" hreflang="en" href="<?=e($canonicalEn)?>"><link rel="alternate" hreflang="ar" href="<?=e($canonicalAr)?>"><link rel="alternate" hreflang="x-default" href="<?=e($canonicalEn)?>"><?php if($preview):?><meta name="robots" content="noindex,nofollow"><?php endif;?><?php $favicon=!empty($settings['favicon_media_id'])?media_by_id((int)$settings['favicon_media_id']):null;if($favicon&&str_starts_with($favicon['mime_type'],'image/')):?><link rel="icon" href="<?=e(site_public_url('uploads/'.rawurlencode($favicon['filename'])))?>" type="<?=e($favicon['mime_type'])?>"><?php endif;?><link rel="stylesheet" href="<?=e(site_public_url('assets/css/site.css?v=4'))?>"><style>:root{--primary:<?=$safeColor($design['primary']??null,'#4f7cff')?>;--secondary:<?=$safeColor($design['secondary']??null,'#10192b')?>;--accent:<?=$safeColor($design['accent']??null,'#61d6e8')?>;--background:<?=$safeColor($design['background']??null,'#08111f')?>;--surface:<?=$safeColor($design['surface']??null,'#101b2c')?>;--text:<?=$safeColor($design['text']??null,'#f4f7fb')?>;--muted:<?=$safeColor($design['muted']??null,'#9aa9bf')?>;--radius:<?=$safeSize($design['radius']??null,'14px')?>;--space:<?=$safeSize($design['spacing']??null,'88px')?>;--base:<?=$safeSize($design['base_size']??null,'16px')?>;--font:<?=$safeFont($design['font']??null,'Arial, sans-serif')?>;--heading-font:<?=$safeFont($design['heading_font']??null,'Arial, sans-serif')?>}</style></head><body><header class="site-header"><a class="logo" href="#top"><?php if(!empty($settings['logo_media_id']))echo image_tag((int)$settings['logo_media_id'],(string)($settings['brand']??'SMayo'),'logo-image');else echo e($settings['brand']??'SMayo');?></a><button class="menu-toggle" aria-expanded="false" aria-label="<?=e($menuOpenLabel)?>">☰</button><nav><?php foreach(($settings['navigation']??[]) as $link):?><a href="<?=e(safe_link($link['href']??'#',$locale))?>"><?=e($link['label']??'')?></a><?php endforeach;?><span class="language-switcher" aria-label="<?=e($languageLabel)?>"><a href="<?=e(localized_page_url('en'))?>" lang="en" hreflang="en" <?=($locale==='en'?'aria-current="page"':'')?> >EN</a><span aria-hidden="true">|</span><a href="<?=e(localized_page_url('ar'))?>" lang="ar" hreflang="ar" <?=($locale==='ar'?'aria-current="page"':'')?> >AR</a></span></nav></header><main id="top"><?php foreach($sections as $section){if(!is_array($section)||empty($section['visible']))continue;echo render_section($section,$settings,$locale);}?></main><footer class="site-footer"><div><strong><?=e($settings['brand']??'SMayo')?></strong><p><?=e($settings['footer']??'')?></p><?php if(!empty($settings['email'])):?><a href="mailto:<?=e($settings['email'])?>"><?=e($settings['email'])?></a><?php endif;?></div><div class="social-links"><?php foreach(($settings['social_links']??[]) as $social):?><a href="<?=e(safe_link($social['href']??'#',$locale))?>" rel="me noopener" target="_blank"><?=e($social['label']??'Social link')?></a><?php endforeach;?></div><span>© <?=date('Y')?> <?=e($settings['brand']??'SMayo')?></span></footer><script src="<?=e(site_public_url('assets/js/site.js?v=4'))?>" defer></script></body></html>
